import { View, Text, Pressable, Alert, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

// Сервер энэ удаа унасан гэж бод — захиалга үргэлж алдаа өгнө.
const fakeOrder = () => new Promise((res, rej) => setTimeout(() => rej(new Error("Сервер алдаа")), 200));

function App() {
  const [ordered, setOrdered] = useState(false);

  function order() {
    setOrdered(true); // optimistic: шууд «захиалсан» болгоно
    fakeOrder()
      .then(() => Alert.alert("Амжилттай", "Захиалга баталгаажлаа"))
      .catch(() => {
        // энд бичнэ үү: алдаа гарсан тул ordered-г false болгож буцаагаад Alert("Алдаа", ...) харуул
      });
  }

  return (
    <View style={styles.s}>
      <Text nativeID="status" style={styles.status}>{ordered ? "Захиалсан" : "Захиалаагүй"}</Text>
      <Pressable nativeID="order" style={styles.btn} onPress={order}><Text style={styles.btnText}>Захиалах</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, alignItems: "center", justifyContent: "center", gap: 16, padding: 24 },
  status: { fontSize: 18, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", paddingHorizontal: 24, paddingVertical: 14, borderRadius: 12 },
  btnText: { color: "#fff", fontWeight: "bold", fontSize: 16 },
});

registerRootComponent(App);

import { View, Text, Pressable, Alert, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

// Сервер энэ удаа унасан гэж бод — захиалга үргэлж алдаа өгнө.
const fakeOrder = () => new Promise((res, rej) => setTimeout(() => rej(new Error("Сервер алдаа")), 200));

function App() {
  const [ordered, setOrdered] = useState(false);

  function order() {
    setOrdered(true); // optimistic: шууд «захиалсан» болгоно
    fakeOrder()
      .then(() => Alert.alert("Амжилттай", "Захиалга баталгаажлаа"))
      .catch(() => {
        setOrdered(false);
        Alert.alert("Алдаа", "Захиалга амжилтгүй. Дахин оролдоно уу.");
      });
  }

  return (
    <View style={styles.s}>
      <Text nativeID="status" style={styles.status}>{ordered ? "Захиалсан" : "Захиалаагүй"}</Text>
      <Pressable nativeID="order" style={styles.btn} onPress={order}><Text style={styles.btnText}>Захиалах</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, alignItems: "center", justifyContent: "center", gap: 16, padding: 24 },
  status: { fontSize: 18, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", paddingHorizontal: 24, paddingVertical: 14, borderRadius: 12 },
  btnText: { color: "#fff", fontWeight: "bold", fontSize: 16 },
});

registerRootComponent(App);
